window.Vibe={base:['localhost','127.0.0.1'].includes(location.hostname)?location.origin:'http://127.0.0.1:4173',token:sessionStorage.getItem('vibe-session')||'',user:null};
Vibe.api=async function(path,body){const response=await fetch(Vibe.base+'/api'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(Vibe.token?{Authorization:'Bearer '+Vibe.token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'Request failed'),{status:response.status});return data;};
Vibe.escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
Vibe.require=async function(options={}){try{Vibe.user=await Vibe.api('/me');return Vibe.user;}catch{return new Promise((resolve,reject)=>{const local=['127.0.0.1','localhost'].includes(location.hostname)&&location.origin===Vibe.base;let admin=local,register=false;const dismissible=options.dismissible??!/^\/(account|practice|studio)(?:\/|$)/.test(location.pathname);const host=document.createElement('dialog');host.className='vibe-auth';host.setAttribute('aria-label','Open Vibe workspace');host.addEventListener('cancel',event=>{event.preventDefault();if(dismissible){host.remove();reject(Error('Access cancelled.'));}});document.body.append(host);host.showModal();function render(){host.innerHTML='<form class="vibe-auth-card"><a href="/frontdoor/">Vibe One / Vibe Law</a><h1>'+(admin?'Your admin workspace':register?'Create your account':'Welcome back')+'</h1><p>'+(admin?'Enter the local admin passkey. No email account needed.':'Your projects, practice space and Codex builds.')+'</p>'+(admin?'<label>Admin passkey<input name="passkey" type="password" required autocomplete="off" autofocus></label>':(register?'<label>Name<input name="name" required autocomplete="name"></label>':'')+'<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" minlength="10" maxlength="200" required autocomplete="'+(register?'new-password':'current-password')+'"></label>'+(register?'<label>Start with<select name="edition"><option value="one">Vibe One</option><option value="law">Vibe Law</option></select></label>':''))+'<p class="vibe-auth-error" role="status"></p><button class="primary">'+(admin?'Admin access':register?'Create account':'Sign in')+'</button>'+(admin?'<button type="button" id="email-access">Use email account</button>':'<button type="button" id="auth-switch">'+(register?'Already have an account? Sign in':'New here? Create an account')+'</button>'+(local?'<button type="button" id="admin-access">Admin access</button>':'<a class="button" href="http://127.0.0.1:4173/practice/">Open local admin access</a>'))+'<small>Admin entry is available only on this computer. Vibe One and Vibe Law are local trials; billing is not connected. Codex uses the computer owner’s signed-in subscription.</small><small><a href="/downloads/">Get the local companion</a>. Start Start-Platform.ps1 if the engine is offline.</small></form>';host.querySelector('#email-access')?.addEventListener('click',()=>{admin=false;register=false;render();});host.querySelector('#admin-access')?.addEventListener('click',()=>{admin=true;render();});host.querySelector('#auth-switch')?.addEventListener('click',()=>{register=!register;render();});const field=host.querySelector('[name=edition]');if(field){let selected=new URLSearchParams(location.search).get('edition');try{selected||=localStorage.getItem('vibe-edition');}catch{}if(['one','law'].includes(selected))field.value=selected;}host.querySelector('form').onsubmit=async event=>{event.preventDefault();const submit=host.querySelector('.primary');submit.disabled=true;try{const data=await Vibe.api('/auth/'+(admin?'admin':register?'register':'login'),Object.fromEntries(new FormData(event.target)));Vibe.token=data.token;Vibe.user=data.user;sessionStorage.setItem('vibe-session',data.token);host.remove();resolve(data.user);}catch(error){host.querySelector('[role=status]').textContent=error.message.includes('fetch')?'Local engine unavailable. Start Start-Platform.ps1.':error.message;submit.disabled=false;}};host.querySelector('input')?.focus();}render();});}};
Vibe.logout=async()=>{await Vibe.api('/auth/logout',{});sessionStorage.removeItem('vibe-session');sessionStorage.removeItem('wb-pair-token');location.href='/account/';};
